WITH itineraries AS (SELECT Flight_Number_Reporting_Airline, IATA_CODE_Reporting_Airline AS Carrier, FlightDate, count() AS hops, arrayStringConcat(arrayConcat(arraySort((x, t) -> t, groupArray(OriginCode), groupArray(assumeNotNull(CRSDepTime))), [argMax(DestCode, assumeNotNull(CRSDepTime))]), '-') AS Route FROM ontime.fact_ontime WHERE Tail_Number != '' AND Cancelled = 0 GROUP BY Flight_Number_Reporting_Airline, IATA_CODE_Reporting_Airline, FlightDate), route_stats AS (SELECT Route, max(hops) AS max_hops, count() AS occurrences, min(FlightDate) AS first_seen, max(FlightDate) AS last_seen FROM itineraries GROUP BY Route) SELECT Route, max_hops, occurrences, first_seen, last_seen FROM route_stats ORDER BY max_hops DESC, occurrences DESC LIMIT 10
